const bcrypt = require('bcryptjs');

const inputPassword = $json["body"]["password"];
const storedSalt = $json["salt"];
const storedHash = $json["hash"];

const hashInputPassword = bcrypt.hashSync(inputPassword, storedSalt);

return [{ match: hashInputPassword === storedHash }];

const jwt = require('jsonwebtoken');

const accessToken = jwt.sign({ username: $json["body"]["username"] }, 'accessSecret', { expiresIn: '15m' });
const refreshToken = jwt.sign({ username: $json["body"]["username"] }, 'refreshSecret', { expiresIn: '7d' });

return [{ accessToken, refreshToken }];
